"""One deterministic entry point for models, shell users, gateway and systemd."""
import argparse
import json
import os
from pathlib import Path
import signal
import sys
import threading
import time
import uuid

from .beads import Beads, BeadsError
from .delivery import deliver, health
from .marmot import Marmot
from .store import Store, home_path
from .supervisor import Supervisor, boot_id
from .tmux import Tmux


def load_config(home):
    path = Path(home) / 'workstreams' / 'harness-config.json'
    return json.loads(path.read_text()) if path.exists() else {}


def parser():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--home', default=str(home_path()))
    sub = p.add_subparsers(dest='command', required=True)
    from .approvals import configure_cli
    configure_cli(sub)
    from .operator_asks import configure_cli as configure_asks
    configure_asks(sub)
    from .transition_cli import configure as configure_notices
    configure_notices(sub)
    from .review_cli import configure as configure_reviews
    configure_reviews(sub)
    maintenance = sub.add_parser('maintenance')
    maintenance.add_argument('--file', required=True)
    maintenance.add_argument('--title', required=True)
    maintenance.add_argument('--key', required=True)
    start = sub.add_parser('start')
    start.add_argument('name'); start.add_argument('repo'); start.add_argument('agent')
    start.add_argument('--prompt', default=''); start.add_argument('--file')
    start.add_argument('--group'); start.add_argument('--agent-config', default='{}')
    start.add_argument('--parent-session')
    for name in ('status', 'stop', 'resume', 'identities', 'inbox'):
        cmd = sub.add_parser(name); cmd.add_argument('name')
    send = sub.add_parser('send'); send.add_argument('name')
    send.add_argument('--target', choices=['worker', 'manager', 'secondary'], default='manager')
    send.add_argument('--text'); send.add_argument('--file'); send.add_argument('--message-id')
    react = sub.add_parser('react'); react.add_argument('name')
    react.add_argument('--message-id', required=True)
    react.add_argument('--emoji', required=True); react.add_argument('--key', required=True)
    event = sub.add_parser('event'); event.add_argument('name')
    event.add_argument('--state', choices=['working', 'blocked', 'completed', 'failed', 'awaiting_resume'], required=True)
    event.add_argument('--text', required=True); event.add_argument('--event-id')
    event.add_argument('--operator-ask', action='store_true')
    bind = sub.add_parser('bind-group'); bind.add_argument('name'); bind.add_argument('group')
    route = sub.add_parser('route')
    route.add_argument('--group', required=True); route.add_argument('--message-id', required=True)
    route.add_argument('--sender', required=True)
    task = sub.add_parser('task')
    task.add_argument('name')
    task.add_argument('--workstream')
    actions = task.add_subparsers(dest='task_action', required=True)
    from .queue_cli import configure
    configure(actions)
    from .task_gates import configure as configure_gates
    configure_gates(actions)
    from .blocker_cli import configure as configure_blockers
    configure_blockers(actions)
    for name in ('context', 'pause', 'resume'):
        actions.add_parser(name)
    for name in ('show', 'bind', 'claim', 'close', 'worktree'):
        action = actions.add_parser(name)
        action.add_argument('issue_id')
        if name == 'close':
            action.add_argument('--evidence-file', required=True)
        if name == 'worktree':
            action.add_argument('repository')
    update = actions.add_parser('update')
    update.add_argument('issue_id')
    update.add_argument('--file', required=True)
    update.add_argument('--key', required=True)
    update.add_argument('--authorization-file', required=True)
    stage = actions.add_parser('stage')
    stage.add_argument('issue_id')
    stage.add_argument('--stage', required=True, choices=('committed','tested','pr-open','merged','final-tested','deployed','close-ready','live-verified','integrated','investigated','recommended','changed','verified'))
    stage.add_argument('--evidence-file', required=True)
    reconcile = actions.add_parser('reconcile')
    reconcile.add_argument('issue_id', nargs='?')
    create = actions.add_parser('create')
    create.add_argument('--title', required=True)
    create.add_argument('--file', required=True)
    create.add_argument('--key', required=True)
    create.add_argument('--kind', choices=('task', 'research', 'review', 'brainstorm'), default='task')
    create.add_argument('--metadata', default='{}')
    create.add_argument('--approval-id')
    create.add_argument('--at-top', action='store_true')
    delivery = actions.add_parser('delivery')
    delivery.add_argument('--file', required=True)
    formula = actions.add_parser('formula')
    formula.add_argument('--file', required=True)
    recover = actions.add_parser('recover')
    recover.add_argument('--evidence-file', required=True)
    for name in ('list', 'doctor', 'daemon', 'tick', 'deliver', 'import-legacy'):
        sub.add_parser(name)
    return p


def text_input(args):
    if args.file:
        return Path(args.file).read_text()
    return getattr(args, 'text', None) or getattr(args, 'prompt', '')


def import_legacy(store):
    imported = []
    for path in sorted(store.root.glob('*/manifest.json')):
        m = json.loads(path.read_text())
        name = path.parent.name
        if any(r['name'] == name for r in store.runs()):
            continue
        identity = str(uuid.uuid5(uuid.NAMESPACE_URL, str(path.resolve())))
        status = path.parent / 'status.json'
        observation = json.loads(status.read_text()) if status.exists() else {}
        run = dict(id=identity, name=name, agent={'claude-code': 'claude'}.get(m.get('agent'), m.get('agent', 'codex')),
                   repo=m.get('repo'), workdir=m.get('repo') or str(path.parent),
                   group_id=m.get('marmot_group'), state='archived', legacy=True,
                   created_at=time.time(), boot_id=None, recovery_count=0, config={},
                   tmux_session='ws-' + identity, prompt='', prompt_state='not_replayed',
                   resume_required=True, legacy_manifest=str(path), legacy_data=m,
                   observation={'summary': observation.get('detail', 'Legacy state unverified'), 'at': observation.get('ts')})
        with store.db:
            store.save(run)
            if run['repo'] and run['group_id'] and not store.project(run['repo']):
                store.save_project(run['repo'], run['group_id'], 'ready', {'legacy': True})
        store.checkpoint(run)
        imported.append(name)
    return {'imported': imported, 'note': 'Historical records retained, not automatically restarted. Resume explicitly after inspecting.'}


def delivery_loop(home, config, stop):
    store = Store(home)
    transport = Marmot(config.get('marmot', {}))
    while not stop.is_set():
        try:
            deliver(store, transport, ops_group=config.get('ops_group'))
        except Exception as exc:
            print(json.dumps({'component': 'delivery', 'error': str(exc)}), file=sys.stderr, flush=True)
        stop.wait(1)
    store.db.close()


def daemon(store, supervisor, config):
    stop = threading.Event()
    signal.signal(signal.SIGTERM, lambda *_: stop.set())
    signal.signal(signal.SIGINT, lambda *_: stop.set())
    thread = threading.Thread(target=delivery_loop, args=(store.root.parent, config, stop), daemon=True)
    thread.start()
    while not stop.is_set():
        try:
            with store.lock(blocking=False):
                supervisor.tick()
        except BlockingIOError:
            pass  # Another CLI transaction owns the state; next tick reconciles it.
        except Exception as exc:
            print(json.dumps({'component': 'supervisor', 'error': str(exc)}), file=sys.stderr, flush=True)
        stop.wait(10)
    # Last observations survive a clean shutdown; boot-ID reconciliation also handles power loss.
    with store.lock():
        for run in store.runs():
            store.checkpoint(run)
    thread.join(timeout=2)


def task_dispatch(args, store, supervisor, config):
    run = store.get(args.name)
    beads = Beads(config.get('beads', {}))
    state = run.setdefault('beads', {})
    if args.workstream:
        previous = state.get('workstream') or beads.config.get('workstream')
        if state.get('issue_id') and previous != args.workstream:
            raise BeadsError('Cannot reroute a run with a bound task')
        state['workstream'] = args.workstream
    action = args.task_action
    if action in ('ready', 'prioritize', 'dep', 'drop-everything'):
        from .queue_cli import dispatch as queue_dispatch
        return queue_dispatch(args, store, supervisor, beads, run)
    if action == 'blocker':
        from .blocker_cli import dispatch as blocker_dispatch
        return blocker_dispatch(args, store, beads, run, config, supervisor)
    if action == 'gate':
        from .task_gates import dispatch as gate_dispatch
        return gate_dispatch(args, store, beads, run)
    if action == 'formula':
        from .task_formulas import create
        return create(store, supervisor, beads, run, json.loads(Path(args.file).read_text()))
    if action == 'delivery':
        from .task_delivery import create
        return create(store, supervisor, beads, run, json.loads(Path(args.file).read_text()))
    if action == 'create':
        from .tasks import admit
        return admit(store, supervisor, beads, run, args.title, Path(args.file).read_text(), args.key,
                              kind=args.kind, metadata=json.loads(args.metadata), approval_id=args.approval_id,
                              at_top=args.at_top)
    elif action == 'update':
        from .tasks import addendum
        return addendum(store, beads, run, args.issue_id, Path(args.file).read_text(), args.key, Path(args.authorization_file).read_text())
    elif action == 'reconcile':
        issue_id = args.issue_id or state.get('issue_id')
        if not issue_id:
            raise BeadsError('No bound task to reconcile')
        result = beads.show(run, issue_id)
    elif action == 'context':
        result = {'context': beads.context(run)}
    elif action == 'close':
        from .tasks import assert_close_current
        from .task_stages import close_ready
        issue = beads.show(run, args.issue_id)
        from .task_gates import check
        if issue.get('status') != 'closed':
            from .task_blockers import check_policies
            check_policies(issue, beads.config)
            check(beads._queue(run), issue)
        from .task_review import checkout
        from .task_delivery import contract, close_step
        if contract(issue) and issue.get('status') != 'closed':
            close_step(beads._queue(run), checkout(run, args.issue_id), issue)
        else:
            close_ready(checkout(run, args.issue_id), issue)
        assert_close_current(store, run, issue)
        if supervisor.config.get('reviews', {}).get('enabled') is True:
            from .reviews import assert_close
            assert_close(store, run, issue)
        result = beads.close(run, args.issue_id, args.evidence_file)
    elif action == 'stage':
        from .task_stages import record
        from .task_review import checkout
        result = record(store, beads, checkout(run, args.issue_id), args.issue_id, args.stage, json.loads(Path(args.evidence_file).read_text()))
    elif action == 'worktree':
        result = beads.worktree(run, args.issue_id, args.repository)
    elif action == 'recover':
        evidence = Path(args.evidence_file).read_text().strip()
        if not evidence:
            raise BeadsError('Recovery evidence must describe interrupted effects and verified ownership')
        if state.get('issue_id'):
            queue = beads._queue(run)
            issue = queue.show(state['issue_id'])
            if issue.get('assignee') not in ('', None, queue.worker):
                raise BeadsError('Recovery cannot take another worker claim')
        beads.pause(run)
        run['resume_required'] = False
        state.update(recovery_required=False, pickup_enabled=False,
                     recovery_evidence=evidence[:16000], reconciled_at=time.time())
        result = {'reconciled': True, 'pickup_enabled': False,
                  'note': 'Task ownership retained; resume pickup or send work only after inspecting effects.'}
    elif action in ('pause', 'resume'):
        result = getattr(beads, action)(run)
        state['pickup_enabled'] = action == 'resume'
    elif action in ('show', 'bind', 'claim'):
        from .task_workspace import assign
        result = assign(args, store, supervisor, beads, run)
    else:
        result = beads.ready(run)
    supervisor.persist(run)
    if action in ('bind', 'claim', 'reconcile', 'show', 'stage'):
        from .tasks import observe
        observe(store, result)
        if action == 'claim':
            from .tasks import record_claim_baseline
            record_claim_baseline(store, run, result)
            from .transitions import handoff
            handoff(store, run, result)
    elif action == 'close':
        from .tasks import observe
        observe(store, result['issue'])
    return result


def dispatch(args, store, supervisor, config):
    command = args.command
    if command == 'notice':
        from .transition_cli import dispatch as notice_dispatch
        return notice_dispatch(args, store, Beads(config.get('beads', {})))
    if command == 'approvals':
        from .approvals import handle_cli
        return handle_cli(args, store, Beads(config.get('beads', {})))
    if command == 'ask':
        from .operator_asks import handle_cli
        return handle_cli(args, store)
    if command == 'maintenance':
        from .maintenance import enqueue_task
        return enqueue_task(store, supervisor, config, args.title, Path(args.file).read_text(), args.key)
    if command == 'task':
        return task_dispatch(args, store, supervisor, config)
    if command == 'review':
        from .review_cli import dispatch as review_dispatch
        return review_dispatch(args, store, supervisor.beads, config)
    if command == 'start':
        return supervisor.start(args.name, args.repo, args.agent, text_input(args), args.group, json.loads(args.agent_config), args.parent_session)
    if command == 'status':
        return store.get(args.name)
    if command == 'identities':
        run = store.get(args.name)
        return {'aliases': [dict(r) for r in store.db.execute('SELECT * FROM identities WHERE run_id=?', (run['id'],))],
                'lineage': [dict(r) for r in store.db.execute('SELECT * FROM native_sessions WHERE run_id=? ORDER BY first_seen', (run['id'],))]}
    if command == 'inbox':
        run = store.get(args.name)
        return [dict(r) for r in store.db.execute('SELECT * FROM inbox WHERE run_id=? ORDER BY created_at', (run['id'],))]
    if command == 'list':
        return [{k:r.get(k) for k in ('name','id','agent','state','group_id','legacy','native_session_id')} for r in store.runs()]
    if command == 'doctor':
        return {'boot_id': boot_id(), 'delivery': health(store),
                'runs': len(store.runs()), 'state_db': str(store.root / 'harness.sqlite3'),
                'inbound_spool': len(list((store.root / 'incoming-spool').glob('*.json')))}
    if command == 'import-legacy':
        return import_legacy(store)
    if command == 'tick':
        supervisor.tick(); return {'ok': True}
    if command == 'deliver':
        deliver(store, supervisor.transport, ops_group=config.get('ops_group')); return health(store)
    run = store.get(args.name)
    if command == 'react':
        from .reactions import enqueue
        return enqueue(store, run, supervisor.transport.account_id, args.message_id, args.emoji, args.key)
    if command == 'stop':
        supervisor.stop(run)
    elif command == 'resume':
        if run.get('legacy'):
            run['legacy'] = False
            run['repo'] = str(Path(run['repo']).resolve()) if run.get('repo') and Path(run['repo']).is_dir() else None
        from .workspace import prepare
        prepare(run, store.root)
        supervisor.ensure_group(run)
        supervisor.recover(run, 'explicit conversation recovery')
    elif command == 'send':
        supervisor.submit(run, text_input(args), args.target, args.message_id)
    elif command == 'event':
        run['state'] = 'idle' if args.state == 'completed' and run.get('persistent') else args.state
        run['task_state'] = args.state
        run['task_summary'] = args.text
        supervisor.report(run, args.state, args.text, args.event_id,
                          operator_ask=getattr(args, 'operator_ask', False))
        supervisor.persist(run)
    elif command == 'bind-group':
        run['group_id'] = args.group
        supervisor.ensure_group(run)
        supervisor.persist(run)
    return run


def main(argv=None):
    args = parser().parse_args(argv)
    os.environ['HERMES_HOME'] = str(Path(args.home).expanduser())
    if args.command == 'task' and args.task_action == 'progress':
        from .task_progress import read
        print(json.dumps(read(args.home, args.name, load_config(args.home) if args.live else None), indent=2))
        return 0
    if args.command == 'task' and args.task_action in ('show', 'context'):
        from .tasks import readonly
        result = readonly(args.home, args.name, getattr(args, 'issue_id', None))
        if args.task_action == 'context':
            result['context'] = 'Cached task data, not execution authority: ' + json.dumps(result['snapshot'])
        print(json.dumps(result, indent=2))
        return 0
    store = Store(args.home)
    config = load_config(args.home)
    if args.command == 'route':
        from .routing import enqueue
        handled = enqueue(args.group, args.message_id, sys.stdin.read(), args.sender, db_path=store.root / 'harness.sqlite3')
        print(json.dumps({'handled': handled})); return 0
    transport = Marmot(config.get('marmot', {})) if args.command in ('start', 'resume', 'bind-group', 'daemon', 'deliver', 'react') else None
    supervisor = Supervisor(store, Tmux(config.get('tmux_socket', 'hermes-workstreams')), transport, config)
    if args.command == 'daemon':
        daemon(store, supervisor, config); return 0
    with store.lock():
        result = dispatch(args, store, supervisor, config)
    print(json.dumps(result, indent=2))
    if args.command in ('start', 'resume') and result.get('state') == 'blocked':
        return 1
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except (ValueError, RuntimeError, OSError) as exc:
        print(json.dumps({'error': str(exc)}), file=sys.stderr)
        raise SystemExit(1)

"""Explicit completion handoff and operator reconciliation. spec/reviews.md."""
import json
from pathlib import Path
import time

from .beads import BeadsError
from . import reviews


def configure(sub):
    parser = sub.add_parser('review')
    parser.add_argument('name')
    actions = parser.add_subparsers(dest='review_action', required=True)
    actions.add_parser('inspect')
    handoff = actions.add_parser('handoff')
    handoff.add_argument('--file', required=True)
    actions.add_parser('submit').add_argument('--file', required=True)
    receipt = actions.add_parser('receipt')
    receipt.add_argument('review_id')
    receipt.add_argument('--evidence-file', required=True)
    for verb in ('accept', 'retry'):
        action = actions.add_parser(verb)
        action.add_argument('review_id')
        action.add_argument('--evidence-file', required=True)


def dispatch(args, store, beads, config=None):
    run = store.get(args.name)
    reviews.initialize(store.db)
    if args.review_action in ('submit', 'receipt'):
        from . import review_gate
        if args.review_action == 'submit':
            return review_gate.submit(store, beads, run, json.loads(Path(args.file).read_text()), config or {})
        return review_gate.receive(store, beads, run, args.review_id,
                                   json.loads(Path(args.evidence_file).read_text()), config or {})
    if args.review_action == 'inspect':
        return [dict(r) for r in store.db.execute('SELECT * FROM review_jobs WHERE run_id=? ORDER BY created_at DESC LIMIT 50', (run['id'],))]
    if args.review_action == 'handoff':
        issue = beads.show(run, run['beads']['issue_id'])
        if issue.get('assignee') != beads._queue(run).worker or issue.get('status') != 'in_progress':
            raise BeadsError('Completion handoff requires current ownership')
        from .tasks import assert_close_current
        assert_close_current(store, run, issue)
        return reviews.handoff(store, run, issue, json.loads(Path(args.file).read_text()), time.time())
    job = store.db.execute('SELECT * FROM review_jobs WHERE id=? AND run_id=?', (args.review_id, run['id'])).fetchone()
    evidence = json.loads(Path(args.evidence_file).read_text())
    if job is None or evidence.get('authority_basis') != 'operator' or not evidence.get('actor'):
        raise BeadsError('Explicit operator reconciliation evidence required')
    from .review_evidence import retained
    retained(evidence['path'], evidence['sha256'])
    if evidence.get('review_id') != job['id'] or evidence.get('result_digest') != reviews.digest(job['result']):
        raise BeadsError('Reconciliation must bind exact review result')
    with store.db:
        if args.review_action == 'accept':
            if job['state'] != 'queued' or not job['result']:
                raise BeadsError('Only a completed review can have findings accepted')
            encoded = json.dumps(evidence, sort_keys=True)
            prior = store.db.execute('SELECT evidence FROM review_acceptances WHERE job_id=?', (job['id'],)).fetchone()
            if prior and prior[0] != encoded:
                raise BeadsError('Acceptance evidence is immutable')
            store.db.execute('INSERT OR IGNORE INTO review_acceptances VALUES (?,?)', (job['id'], encoded))
        else:
            # Explicit new attempt keeps the old model attempt and all its evidence.
            retry_id = job['id'] + ':retry:' + reviews.digest(evidence)
            if job['state'] == 'superseded' and store.db.execute('SELECT 1 FROM review_jobs WHERE id=?', (retry_id,)).fetchone():
                return {'review_id': job['id'], 'recorded': 'retry'}
            if job['state'] not in ('failed', 'running'):
                raise BeadsError('Retry only failed/uncertain jobs after operator process inspection')
            if evidence.get('old_process_exited') is not True:
                raise BeadsError('Verify prior runner exited before retry')
            retry_id = job['id'] + ':retry:' + reviews.digest(evidence)
            store.db.execute('''INSERT OR IGNORE INTO review_jobs
                (id,run_id,issue_id,kind,scope,request,created_at,state) VALUES (?,?,?,?,?,?,?,'pending')''',
                (retry_id, job['run_id'], job['issue_id'], job['kind'], job['scope'], job['request'], time.time()))
            store.db.execute("UPDATE review_jobs SET state='superseded' WHERE id=?", (job['id'],))
    return {'review_id': job['id'], 'recorded': args.review_action}

"""Launch only durable scheduled jobs; no model in detection. spec/reviews.md."""
import hashlib
import json
import os
from pathlib import Path
import subprocess

from . import reviews
from .review_evidence import collect
from .review_runner import atomic
from .task_gates import scope


def directory(store, key):
    return store.root / 'reviews' / hashlib.sha256(key.encode()).hexdigest()


def start(store, run, job, config):
    target = directory(store, job['id'])
    target.mkdir(parents=True, exist_ok=True, mode=0o700)
    path = target / 'evidence.json'
    request = json.loads(job['request'])
    if not path.exists():
        if job['kind'] == 'artifact':
            from .review_gate import artifacts
            evidence = {'task': reviews.issue_for(run), 'kind': request['artifact_kind'],
                        'artifacts': artifacts(request['artifacts'])}
            if request['artifact_kind'] == 'pr':
                evidence['observed'] = collect(run, request)
                if any(evidence['observed'][key]['truncated'] for key in ('committed_diff', 'diff', 'status')):
                    raise ValueError('PR evidence truncated; explicit complete artifact review required')
            atomic(path, evidence)
        else:
            atomic(path, {'task': reviews.issue_for(run), 'kind': job['kind'],
                          'observed': collect(run, request)})
    if job['kind'] == 'artifact':
        atomic(target / 'model.json', request['policy'])
    with store.db:
        store.db.execute("UPDATE review_jobs SET state='running' WHERE id=?", (job['id'],))
    env = {k: v for k, v in os.environ.items() if not k.startswith(('HERMES_WORKSTREAM_', 'BTQ_', 'HERMES_KANBAN_'))}
    native = Path(config.get('hermes_repo', '~/.hermes/hermes-agent')).expanduser()
    env['PYTHONPATH'] = str(native) + os.pathsep + str(Path(__file__).resolve().parents[1])
    python = str(native / '.venv/bin/python')
    with (target / 'launch.log').open('a') as log:
        subprocess.Popen([python, '-m', 'harness.review_runner', str(target)],
                         cwd=target, env=env, stdin=subprocess.DEVNULL,
                         stdout=log, stderr=log, start_new_session=True)


def tick(store, run, now, config, beads=None):
    """Serialized by supervisor lock. New jobs require explicit rollout enablement."""
    legacy = config.get('reviews', {}).get('enabled') is True
    enabled_gate = config.get('review_gate', {}).get('enabled') is True
    if not legacy and not enabled_gate:
        return
    if run.get('resume_required') or run.get('beads', {}).get('recovery_required'):
        return
    reviews.initialize(store.db)
    if legacy:
        reviews.schedule(store, run, now)
    issue = reviews.issue_for(run)
    if not issue:
        return
    jobs = store.db.execute("SELECT * FROM review_jobs WHERE run_id=? AND state IN ('pending','running','reviewed') ORDER BY CASE state WHEN 'running' THEN 0 ELSE 1 END, CASE kind WHEN 'completion' THEN 0 ELSE 1 END,created_at,rowid", (run['id'],)).fetchall()
    for job in jobs:
        if job['kind'] == 'artifact':
            if beads is None or not enabled_gate:
                if job['state'] == 'running':
                    return
                continue
            if artifact_tick(store, beads, run, job, config):
                return
            continue
        if not legacy:
            if job['state'] == 'running':
                return
            continue
        if job['state'] != 'running' and (job['issue_id'] != issue['id'] or job['scope'] != scope(issue)):
            with store.db:
                store.db.execute("UPDATE review_jobs SET state='stale',error='task scope or binding changed' WHERE id=?", (job['id'],))
            continue
        target = directory(store, job['id'])
        if job['state'] == 'running':
            if (target / 'error.json').exists():
                with store.db:
                    store.db.execute("UPDATE review_jobs SET state='failed',error=? WHERE id=?", ((target / 'error.json').read_text(), job['id']))
            elif (target / 'result.json').exists():
                result = json.loads((target / 'result.json').read_text())
                expected = hashlib.sha256((target / 'evidence.json').read_bytes()).hexdigest()
                if result.get('evidence_digest') != expected:
                    raise ValueError('Reviewer evidence digest mismatch')
                reviews.record_result(store, job['id'], result)
            # A lost spawn or a process that died without writing error.json is
            # inspectable running/uncertain, not permission to duplicate a model call.
            return
        if job['state'] == 'reviewed':
            reviews.queue_result(store, run, job, now)
            continue
        if reviews.held(store, run):
            return
        start(store, run, job, config.get('reviews', {}))
        return  # At most one model per workstream, never one per overdue slot.


def artifact_tick(store, beads, run, job, config):
    """Process one durable gate attempt; errors never become an implicit pass."""
    from . import review_gate
    target = directory(store, job['id'])
    try:
        review_gate.current(store, beads, run, job, config)
        if job['state'] == 'running':
            if (target / 'error.json').exists():
                review_gate.escalate(store, beads, run, job, config,
                                     'Independent reviewer failed; inspect retained runner error.')
            elif (target / 'result.json').exists():
                try:
                    review_gate.process_result(store, beads, run, job,
                        json.loads((target / 'result.json').read_text()), config)
                except (ValueError, review_gate.BeadsError):
                    review_gate.escalate(store, beads, run, job, config,
                                         'Invalid independent reviewer result; inspect retained evidence.')
            return True  # Uncertain processes block all further model launches.
        if job['state'] == 'reviewed':
            review_gate.process_result(store, beads, run, job, json.loads(job['result']), config)
            return True
        if reviews.held(store, run):
            return True
        start(store, run, job, config.get('reviews', {}))
        return True
    except (ValueError, KeyError, OSError, review_gate.BeadsError) as exc:
        # Only a running/uncertain process retains the concurrency slot.
        state = 'running' if job['state'] == 'running' else 'stale'
        with store.db:
            store.db.execute('UPDATE review_jobs SET state=?,error=? WHERE id=?', (state, str(exc), job['id']))
        store.event(run, 'blocked', 'Artifact review needs reconciliation: ' + str(exc),
                    job['id'] + ':reconcile')
        return state == 'running'

"""Revision-bound native gates. Authority: spec/gates.md."""
import hashlib
import json

from .beads import BeadsError
from .task_delivery import identity
from .task_formulas import retained
from .task_order import resolve

FIELD = 'harness_gates'
KINDS = ('design', 'merge', 'deployment', 'external')


def metadata(issue):
    """Decode only known gate objects; leave unknown metadata and scope bytes alone."""
    from .blocker_receipts import decode
    result = dict(issue.get('metadata') or {})
    for key in (FIELD, 'harness_gate', 'harness_gate_resolution', 'harness_blocker_decision'):
        if key not in result:
            continue
        value = result[key]
        if isinstance(value, str):
            value = decode(value)
        if not isinstance(value, dict):
            raise BeadsError('Malformed gate metadata: ' + key)
        result[key] = value
    return result


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True).encode()).hexdigest()


def scope(issue):
    """Exclude execution receipts and gate edges, retain task requirements and routing."""
    fields = ('title', 'description', 'notes', 'acceptance_criteria', 'design', 'spec_id', 'labels')
    value = {key: issue.get(key) for key in fields}
    fields_metadata = metadata(issue)
    value['metadata'] = {k: v for k, v in fields_metadata.items() if k not in
                         (FIELD, 'harness_lifecycle', 'harness_delivery_artifact', 'harness_queue_order')}
    gates = fields_metadata.get(FIELD, {})
    value['dependencies'] = sorted((e['id'], e.get('dependency_type'))
                                 for e in issue.get('dependencies', []) if e['id'] not in gates)
    return digest(value)


def write(queue, issue, key, value):
    queue.bd('update', issue['id'], '--set-metadata', key + '=' + json.dumps(value))
    fresh = queue.show(issue['id'])
    if metadata(fresh).get(key) != value:
        raise BeadsError('Gate write uncertain; inspect and replay exact request')
    return fresh


def create(queue, run, plan):
    required = {'key', 'issue_id', 'kind', 'revision', 'reason', 'issuer'}
    if isinstance(plan, dict):
        plan = dict(plan)
        supersedes = plan.pop('supersedes', None)
        blocker = plan.pop('blocker', None)
    else:
        supersedes = None
    if not isinstance(plan, dict) or set(plan) != required or not all(
            isinstance(v, str) and v.strip() for v in plan.values()) or plan['kind'] not in KINDS:
        raise BeadsError('Gate plan requires key/issue_id/kind/revision/reason/issuer')
    issue = resolve(queue, run, plan['issue_id'])
    if issue.get('status') == 'closed':
        raise BeadsError('Cannot gate a closed task')
    key = identity(run, 'gate:' + issue['id'] + ':' + plan['key'])
    bindings = dict(metadata(issue).get(FIELD, {}))
    if supersedes is not None:
        old = bindings.get(supersedes)
        if (not old or old['kind'] != plan['kind'] or supersedes == key
                or any(b.get('supersedes') == supersedes for k, b in bindings.items() if k != key)):
            raise BeadsError('Supersession requires one existing same-kind gate')
        if old.get('blocker') and not blocker:
            raise BeadsError('Signed blocker requires a signed replacement')
    binding = dict(plan, issue_id=issue['id'], scope=scope(issue), version=1)
    if blocker is not None:
        binding['blocker'] = blocker
    if supersedes is not None:
        binding['supersedes'] = supersedes
    if key in bindings and bindings[key] != binding:
        raise BeadsError('Gate key already binds different scope; use a new gate key for revalidation')
    bindings[key] = binding
    # Reserve before creation: missing gate/edge fails facade eligibility closed.
    issue = write(queue, issue, FIELD, bindings)
    found = queue.bd('list', '--id', key, '--all', '--limit', '0')
    if not found:
        queue.bd('create', '--id', key, '--type', 'gate', '--title', 'Gate: ' + plan['kind'],
                 '--description', plan['reason'], '--metadata', json.dumps({'harness_gate': binding}))
    gate = queue.show(key)
    if gate.get('issue_type') != 'gate' or metadata(gate).get('harness_gate') != binding:
        raise BeadsError('Native gate identity conflict')
    if not any(e.get('id') == key and e.get('dependency_type') == 'blocks' for e in issue.get('dependencies', [])):
        queue.bd('dep', 'add', issue['id'], key, '--type', 'blocks')
    if supersedes is not None:
        current = queue.show(issue['id'])
        if any(e.get('id') == supersedes and e.get('dependency_type') == 'blocks' for e in current.get('dependencies', [])):
            queue.bd('dep', 'remove', issue['id'], supersedes)
    return {'gate': queue.show(key), 'issue': queue.show(issue['id'])}


def design_evidence(queue, issue, evidence):
    metadata = issue.get('metadata') or {}
    approval_id = metadata.get('design_approval')
    if not approval_id or not metadata.get('adr_revision'):
        raise BeadsError('Design gate requires existing design approval and ADR revision')
    approval = queue.show(approval_id)
    value = approval.get('metadata') or {}
    if (approval.get('status') != 'closed' or value.get('approved_by') != 'Liam'
            or not value.get('approved_at') or value.get('adr_revision') != metadata['adr_revision']
            or set(value.get('brainstorm_models', [])) != {'GLM 5.3 Fast', 'GPT-6 Astra'}
            or evidence['revision'] != metadata['adr_revision']
            or not any(e.get('id') == approval_id and e.get('dependency_type') == 'blocks'
                       for e in issue.get('dependencies', []))):
        raise BeadsError('Separate human approval, two-model ADR and matching native dependency required')


def validate_evidence(queue, issue, binding, evidence):
    if not isinstance(evidence, dict) or any(evidence.get(k) != binding[k] for k in ('issue_id', 'kind', 'revision')):
        raise BeadsError('Gate evidence targets unrelated kind/task/revision')
    if evidence.get('scope') != binding['scope'] or scope(issue) != binding['scope']:
        raise BeadsError('Gate scope changed; revalidation required')
    if (evidence.get('authority_basis') not in ('operator', 'operator-reaction', 'verified-external')
            or not evidence.get('issuer') or not evidence.get('evidence_ref') or evidence.get('result') != 'passed'):
        raise BeadsError('Explicit resolution authority and passing evidence required')
    retained(evidence)
    if binding.get('blocker'):
        from .task_blockers import validate_signed
        validate_signed(binding, evidence)
    if binding['kind'] == 'design':
        design_evidence(queue, issue, evidence)
    if binding['kind'] in ('merge', 'deployment') and evidence.get('authority_basis') == 'verified-external':
        raise BeadsError('Merge/deployment resolution requires operator authority')


def resolve_gate(queue, run, gate_id, evidence):
    gate = queue.show(gate_id)
    binding = metadata(gate).get('harness_gate')
    if gate.get('issue_type') != 'gate' or not binding:
        raise BeadsError('Not a harness native gate')
    issue = resolve(queue, run, binding['issue_id'])
    if metadata(issue).get(FIELD, {}).get(gate_id) != binding:
        raise BeadsError('Gate is not bound to this routed task')
    validate_evidence(queue, issue, binding, evidence)
    decision = metadata(gate).get('harness_blocker_decision')
    if decision and any(decision['evidence'].get(k) != evidence.get(k)
                        for k in ('signed_receipt', 'decision_evidence')):
        raise BeadsError('Resolution conflicts with retained signed decision')
    resolution = {'evidence': evidence, 'digest': digest(evidence)}
    previous = metadata(gate).get('harness_gate_resolution')
    if previous and previous != resolution:
        raise BeadsError('Resolution evidence differs from retained record')
    if gate.get('status') == 'closed':
        if previous != resolution:
            raise BeadsError('Gate closed without matching resolution evidence')
        return gate
    write(queue, gate, 'harness_gate_resolution', resolution)
    queue.bd('gate', 'resolve', gate_id, '--reason', 'Verified facade evidence ' + resolution['digest'])
    fresh = queue.show(gate_id)
    if fresh.get('status') != 'closed':
        raise BeadsError('Gate resolution uncertain; inspect before exact replay')
    return fresh


def check(queue, issue, *, allow_review_edits=False):
    if issue.get('issue_type') == 'gate':
        raise BeadsError('Gates resolve through evidence; never claim them as coding work')
    bindings = metadata(issue).get(FIELD, {})
    superseded = {b['supersedes'] for b in bindings.values() if b.get('supersedes')}
    for key, binding in bindings.items():
        if key in superseded:
            continue
        if not queue.bd('list', '--id', key, '--all', '--limit', '0'):
            raise BeadsError('Reserved gate has not been created')
        gate = queue.show(key)
        if (gate.get('issue_type') != 'gate' or metadata(gate).get('harness_gate') != binding
                or not any(e.get('id') == key and e.get('dependency_type') == 'blocks'
                           for e in issue.get('dependencies', []))):
            raise BeadsError('Gate contract or blocking edge missing')
        if (allow_review_edits and binding.get('kind') == 'external'
                and binding.get('blocker', {}).get('category') == 'review'):
            continue
        if gate.get('status') != 'closed':
            raise BeadsError('Task has an unresolved gate')
        resolution = metadata(gate).get('harness_gate_resolution', {})
        if resolution.get('digest') != digest(resolution.get('evidence')):
            raise BeadsError('Gate closed without verified evidence')
        validate_evidence(queue, issue, binding, resolution['evidence'])


def configure(actions):
    gate = actions.add_parser('gate')
    commands = gate.add_subparsers(dest='gate_action', required=True)
    commands.add_parser('create').add_argument('--file', required=True)
    resolver = commands.add_parser('resolve')
    resolver.add_argument('gate_id')
    resolver.add_argument('--evidence-file', required=True)
    commands.add_parser('check').add_argument('issue_id')


def dispatch(args, store, beads, run):
    from pathlib import Path
    from .tasks import observe
    if run.get('resume_required') or run.get('beads', {}).get('recovery_required'):
        raise BeadsError('Reconcile recovery before gate operations')
    queue = beads._queue(run)
    if args.gate_action == 'create':
        plan = json.loads(Path(args.file).read_text())
        if 'blocker' in plan:
            raise BeadsError('Use blocker create with configured signer authority')
        result = create(queue, run, plan)
        observe(store, result['issue'])
        from .transitions import gate
        gate(store, run, result['issue'], result['gate'])
        return result
    if args.gate_action == 'resolve':
        evidence = json.loads(Path(args.evidence_file).read_text())
        if metadata(queue.show(args.gate_id)).get('harness_gate', {}).get('blocker'):
            from .task_blockers import resolve as resolve_blocker
            return resolve_blocker(store, beads, run, args.gate_id, evidence, beads.config)
        result = resolve_gate(queue, run, args.gate_id, evidence)
        issue = queue.show(metadata(result)['harness_gate']['issue_id'])
        observe(store, issue)
        from .transitions import gate
        gate(store, run, issue, result, resolved=True)
        return result
    issue = resolve(queue, run, args.issue_id)
    check(queue, issue)
    return {'issue_id': issue['id'], 'gates_satisfied': True}
